import requests, re, html as html_mod

headers = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36'}

# Try Bing HTML
for q in ['Marcus Webb Book Cellar', 'Sarah Chen Northfield Academy', 'Angela Torres Hope Fellowship']:
    print(f'=== {q} ===')
    try:
        r = requests.get('https://www.bing.com/search', params={'q': q}, headers=headers, timeout=10)
        # Look for result titles
        titles = re.findall(r'<h2><a[^>]*href=\"(https?://[^\"]+)\"[^>]*>(.*?)</a></h2>', r.text, re.DOTALL)
        snippets = re.findall(r'<p[^>]*class=\"b_lineclamp[^\"]*\"[^>]*>(.*?)</p>', r.text, re.DOTALL)
        if titles:
            for i, (url, title) in enumerate(titles[:5]):
                title = re.sub(r'<[^>]+>', '', title).strip()
                snippet = re.sub(r'<[^>]+>', '', snippets[i]).strip() if i < len(snippets) else ''
                print(f'  {i+1}. {html_mod.unescape(title)}')
                print(f'     {url}')
                print(f'     {html_mod.unescape(snippet[:200])}')
        else:
            print(f'  No standard results. Page size: {len(r.text)}')
            if 'captcha' in r.text.lower() or 'challenge' in r.text.lower() or 'sorry' in r.text.lower():
                print('  (blocked by captcha/challenge)')
    except Exception as e:
        print(f'  Error: {e}')
    print()
" 2>&1", "timeout": 60}
